// GENERATED by scripts/build-io.mjs from src/ - edit the source, not this file.
// Products as a horizontal carousel. Each card: the image and name lead to the
// PDP, the price shows only what the payload carried, and "Adicionar" writes
// the shopper's real VTEX cart (see cart.ts).
import React, { useCallback, useEffect, useRef, useState } from 'react';
import type { ChatProduct } from './mapMessage';
import { parseRetailerId } from './cart';
import { resolveProductUrl } from './product';
import { BoxIcon, CartIcon, CheckIcon, ChevronLeftIcon, ChevronRightIcon } from './icons';

/** How long "Adicionado" stays up before the button goes back to idle. */
const DONE_MS = 2200;

function price(value: number): string {
  return value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

/**
 * Opens the PDP in a new tab, so the chat injected into this page survives.
 * Without `product_url` the link is looked up from the SKU; the tab is opened
 * synchronously inside the click so the popup blocker lets it through.
 */
function ProductLink({ product, children }: { product: ChatProduct; children: React.ReactNode }) {
  const [url, setUrl] = useState(product.url);
  const [missing, setMissing] = useState(false);

  if (url) {
    return (
      <a className="krc-card-link" href={url} target="_blank" rel="noopener noreferrer" title={product.name}>
        {children}
      </a>
    );
  }

  async function resolve() {
    const sku = parseRetailerId(product.key, product.sellerId)?.skuId;
    if (!sku) return setMissing(true);
    const tab = window.open('about:blank', '_blank');
    const resolved = await resolveProductUrl(sku);
    if (resolved && tab) {
      tab.location.href = resolved;
      setUrl(resolved);
    } else {
      tab?.close();
      setMissing(true);
    }
  }

  return (
    <button
      type="button"
      className="krc-card-link"
      onClick={resolve}
      disabled={missing}
      title={missing ? 'Página do produto indisponível' : product.name}
    >
      {children}
    </button>
  );
}

type AddPhase = 'idle' | 'adding' | 'added';

function AddButton({
  product,
  onAdd,
  mode,
}: {
  product: ChatProduct;
  onAdd: (product: ChatProduct) => Promise<boolean>;
  mode: 'vtex' | 'link';
}) {
  const [phase, setPhase] = useState<AddPhase>('idle');
  const doneTimer = useRef<number | undefined>(undefined);

  useEffect(() => () => window.clearTimeout(doneTimer.current), []);

  async function add() {
    if (phase !== 'idle') return;
    setPhase('adding');
    const ok = await onAdd(product);
    setPhase(ok ? 'added' : 'idle');
    if (ok) doneTimer.current = window.setTimeout(() => setPhase('idle'), DONE_MS);
  }

  return (
    <button
      type="button"
      className={`krc-card-add${phase === 'added' ? ' is-added' : ''}`}
      onClick={add}
      disabled={phase === 'adding'}
      aria-label={mode === 'link' ? `Ver ${product.name} no site` : `Adicionar ${product.name} ao carrinho`}
    >
      {phase === 'added' ? <CheckIcon size={15} /> : <CartIcon size={15} />}
      <span aria-live="polite">
        {phase === 'added'
          ? mode === 'link'
            ? 'Aberto'
            : 'Adicionado'
          : phase === 'adding'
            ? mode === 'link'
              ? 'Abrindo…'
              : 'Adicionando…'
            : mode === 'link'
              ? 'Ver peça'
              : 'Adicionar'}
      </span>
    </button>
  );
}

export default function ProductCarousel({
  products,
  header,
  onAdd,
  mode = 'vtex',
}: {
  products: ChatProduct[];
  header?: string;
  onAdd: (product: ChatProduct) => Promise<boolean>;
  mode?: 'vtex' | 'link';
}) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [canPrev, setCanPrev] = useState(false);
  const [canNext, setCanNext] = useState(false);

  const measure = useCallback(() => {
    const track = trackRef.current;
    if (!track) return;
    setCanPrev(track.scrollLeft > 4);
    setCanNext(track.scrollLeft + track.clientWidth < track.scrollWidth - 4);
  }, []);

  useEffect(() => {
    measure();
    // The panel can be expanded, which changes how many cards fit.
    const observer = new ResizeObserver(measure);
    if (trackRef.current) observer.observe(trackRef.current);
    return () => observer.disconnect();
  }, [measure, products.length]);

  /** One card per step: the card's width plus the gap. */
  function step(direction: 1 | -1) {
    const track = trackRef.current;
    const card = track?.firstElementChild as HTMLElement | null;
    if (!track || !card) return;
    const gap = parseFloat(getComputedStyle(track).columnGap) || 0;
    track.scrollBy({ left: direction * (card.offsetWidth + gap), behavior: 'smooth' });
  }

  return (
    <div className="krc-carousel">
      {(header || canPrev || canNext) && (
        <div className="krc-carousel-bar">
          <span className="krc-products-header">{header}</span>
          {(canPrev || canNext) && (
            <span className="krc-carousel-nav">
              <button type="button" onClick={() => step(-1)} disabled={!canPrev} aria-label="Produtos anteriores">
                <ChevronLeftIcon size={15} />
              </button>
              <button type="button" onClick={() => step(1)} disabled={!canNext} aria-label="Próximos produtos">
                <ChevronRightIcon size={15} />
              </button>
            </span>
          )}
        </div>
      )}

      <div className="krc-carousel-track" ref={trackRef} onScroll={measure} role="list">
        {products.map((product) => (
          <div key={product.key} className="krc-card" role="listitem">
            <ProductLink product={product}>
              <span className="krc-card-image">
                {product.image ? <img src={product.image} alt="" loading="lazy" /> : <BoxIcon size={28} />}
              </span>
              <span className="krc-card-name">{product.name}</span>
            </ProductLink>

            {product.price !== undefined && (
              <span className="krc-card-price">
                {product.listPrice !== undefined && <s>{price(product.listPrice)}</s>}
                <strong>{price(product.price)}</strong>
              </span>
            )}

            <AddButton product={product} onAdd={onAdd} mode={mode} />
          </div>
        ))}
      </div>
    </div>
  );
}
